    "longExplanation": "The ～どうですか grammar point is Dùng để hỏi for someone's opinion or suggestion on something. Có thể dịch là 'how about' or 'what do you think of' trong câu. This expression is neither casual nor super-formal, and can be used in various situations.",
    "formation": "Danh từ + は/が + どうですか / Động từ-casual + の + どうですか / い-Tính từ + どうですか / な-Tính từ + な + どうですか"
