    "longExplanation": "The ～どう言いますか grammar point is Dùng để hỏi someone how to express something in a particular language or the appropriate way to say it. Có thể dịch là 'how do you say' trong câu.",
    "formation": "Word/Phrase + は [language]でどう言いますか / Word/Phrase + をどう言いますか"
