    "shortExplanation": "Diễn tả the time when something happens, 'when', 'at the time'.",
    "longExplanation": "The ～とき grammar point is Dùng để diễn tả the time when something happens or happened. Có thể dịch là 'when' or 'at the time' trong câu. The formation differs depending on whether it is used with a verb, い-adjective, な-adjective, or noun.",
