    "longExplanation": "The grammar point ときどき is an adverb used to describe an event or action that occurs occasionally or at irregular intervals. Có thể dịch là 'sometimes', 'occasionally', or 'now and then' trong câu. It is often Dùng để biểu thị that the speaker cannot predict the exact time when a certain event occurs.",
