    "longExplanation": "The どちら grammar point is Dùng để hỏi about two choices or options. It translates to 'which of the two' or simply 'which' trong câu. It is commonly used with question words like どちらが or どちらを and can be combined with verbs, adjectives, and nouns to ask about preferences or to make comparisons.",
